337	  static final class Part<T> extends ParameterHandler<T> {
338	    private final Method method;
339	    private final int p;
340	    private final okhttp3.Headers headers;
341	    private final Converter<T, RequestBody> converter;
342	
343	    Part(Method method, int p, okhttp3.Headers headers, Converter<T, RequestBody> converter) {
344	      this.method = method;
345	      this.p = p;
346	      this.headers = headers;
347	      this.converter = converter;
348	    }
