350	    @Override
351	    void apply(RequestBuilder builder, @Nullable T value) {
352	      if (value == null) return; // Skip null values.
353	
354	      RequestBody body;
355	      try {
356	        body = converter.convert(value);
357	      } catch (IOException e) {
358	        throw Utils.parameterError(method, p, "Unable to convert " + value + " to RequestBody", e);
