18	import java.io.IOException;
19	import java.lang.annotation.Annotation;
20	import java.lang.reflect.ParameterizedType;
21	import java.lang.reflect.Type;
22	import java.util.Objects;
23	import java.util.concurrent.Executor;
24	import javax.annotation.Nullable;
25	import okhttp3.Request;
26	import okio.Timeout;
27	
28	final class DefaultCallAdapterFactory extends CallAdapter.Factory {
29	  private final @Nullable Executor callbackExecutor;
30	
31	  DefaultCallAdapterFactory(@Nullable Executor callbackExecutor) {
32	    this.callbackExecutor = callbackExecutor;
33	  }
34	
35	  @Override
36	  public @Nullable CallAdapter<?, ?> get(
37	      Type returnType, Annotation[] annotations, Retrofit retrofit) {
38	    if (getRawType(returnType) != Call.class) {
39	      return null;
40	    }
41	    if (!(returnType instanceof ParameterizedType)) {
42	      throw new IllegalArgumentException(
43	          "Call return type must be parameterized as Call<Foo> or Call<? extends Foo>");
44	    }
45	    final Type responseType = Utils.getParameterUpperBound(0, (ParameterizedType) returnType);
46	
47	    final Executor executor =
48	        Utils.isAnnotationPresent(annotations, SkipCallbackExecutor.class)
49	            ? null
50	            : callbackExecutor;
51	
52	    return new CallAdapter<Object, Call<?>>() {
53	      @Override
54	      public Type responseType() {
55	        return responseType;
56	      }
57	
58	      @Override
59	      public Call<Object> adapt(Call<Object> call) {
60	        return executor == null ? call : new ExecutorCallbackCall<>(executor, call);
61	      }
62	    };
63	  }
64	
65	  static final class ExecutorCallbackCall<T> implements Call<T> {
66	    final Executor callbackExecutor;
67	    final Call<T> delegate;
68	
69	    ExecutorCallbackCall(Executor callbackExecutor, Call<T> delegate) {
70	      this.callbackExecutor = callbackExecutor;
71	      this.delegate = delegate;
72	    }
73	
74	    @Override
75	    public void enqueue(final Callback<T> callback) {
76	      Objects.requireNonNull(callback, "callback == null");
77	
78	      delegate.enqueue(
79	          new Callback<T>() {
80	            @Override
81	            public void onResponse(Call<T> call, final Response<T> response) {
82	              callbackExecutor.execute(
83	                  () -> {
84	                    if (delegate.isCanceled()) {
85	                      // Emulate OkHttp's behavior of throwing/delivering an IOException on
86	                      // cancellation.
87	                      callback.onFailure(ExecutorCallbackCall.this, new IOException("Canceled"));
88	                    } else {
89	                      callback.onResponse(ExecutorCallbackCall.this, response);
90	                    }
91	                  });
92	            }
93	
94	            @Override
95	            public void onFailure(Call<T> call, final Throwable t) {
96	              callbackExecutor.execute(() -> callback.onFailure(ExecutorCallbackCall.this, t));
97	            }
98	          });
99	    }
100	
101	    @Override
102	    public boolean isExecuted() {
103	      return delegate.isExecuted();
104	    }
105	
106	    @Override
107	    public Response<T> execute() throws IOException {
108	      return delegate.execute();
109	    }
110	
111	    @Override
112	    public void cancel() {
113	      delegate.cancel();
114	    }
115	
116	    @Override
117	    public boolean isCanceled() {
118	      return delegate.isCanceled();
119	    }
120	
121	    @SuppressWarnings("CloneDoesntCallSuperClone") // Performing deep clone.
122	    @Override
123	    public Call<T> clone() {
124	      return new ExecutorCallbackCall<>(callbackExecutor, delegate.clone());
125	    }
126	
127	    @Override
128	    public Request request() {
129	      return delegate.request();
130	    }
131	
132	    @Override
133	    public Timeout timeout() {
134	      return delegate.timeout();
135	    }
136	  }
137	}
