16	package retrofit2;
17	
18	import android.annotation.TargetApi;
19	import java.lang.annotation.Annotation;
20	import java.lang.reflect.ParameterizedType;
21	import java.lang.reflect.Type;
22	import java.util.concurrent.CompletableFuture;
23	import javax.annotation.Nullable;
24	import org.codehaus.mojo.animal_sniffer.IgnoreJRERequirement;
25	
26	@IgnoreJRERequirement // Only added when CompletableFuture is available (Java 8+ / Android API 24+).
27	@TargetApi(24)
28	final class CompletableFutureCallAdapterFactory extends CallAdapter.Factory {
29	  @Override
30	  public @Nullable CallAdapter<?, ?> get(
31	      Type returnType, Annotation[] annotations, Retrofit retrofit) {
32	    if (getRawType(returnType) != CompletableFuture.class) {
33	      return null;
34	    }
35	    if (!(returnType instanceof ParameterizedType)) {
36	      throw new IllegalStateException(
37	          "CompletableFuture return type must be parameterized"
38	              + " as CompletableFuture<Foo> or CompletableFuture<? extends Foo>");
39	    }
40	    Type innerType = getParameterUpperBound(0, (ParameterizedType) returnType);
41	
42	    if (getRawType(innerType) != Response.class) {
43	      // Generic type is not Response<T>. Use it for body-only adapter.
44	      return new BodyCallAdapter<>(innerType);
45	    }
46	
47	    // Generic type is Response<T>. Extract T and create the Response version of the adapter.
48	    if (!(innerType instanceof ParameterizedType)) {
49	      throw new IllegalStateException(
50	          "Response must be parameterized" + " as Response<Foo> or Response<? extends Foo>");
51	    }
52	    Type responseType = getParameterUpperBound(0, (ParameterizedType) innerType);
53	    return new ResponseCallAdapter<>(responseType);
54	  }
55	
56	  @IgnoreJRERequirement
57	  private static final class BodyCallAdapter<R> implements CallAdapter<R, CompletableFuture<R>> {
58	    private final Type responseType;
59	
60	    BodyCallAdapter(Type responseType) {
61	      this.responseType = responseType;
62	    }
63	
64	    @Override
65	    public Type responseType() {
66	      return responseType;
67	    }
68	
69	    @Override
70	    public CompletableFuture<R> adapt(final Call<R> call) {
71	      CompletableFuture<R> future = new CallCancelCompletableFuture<>(call);
72	      call.enqueue(new BodyCallback(future));
73	      return future;
74	    }
75	
76	    @IgnoreJRERequirement
77	    private class BodyCallback implements Callback<R> {
78	      private final CompletableFuture<R> future;
79	
80	      public BodyCallback(CompletableFuture<R> future) {
81	        this.future = future;
82	      }
83	
84	      @Override
85	      public void onResponse(Call<R> call, Response<R> response) {
86	        if (response.isSuccessful()) {
87	          future.complete(response.body());
88	        } else {
89	          future.completeExceptionally(new HttpException(response));
90	        }
91	      }
92	
93	      @Override
94	      public void onFailure(Call<R> call, Throwable t) {
95	        future.completeExceptionally(t);
96	      }
97	    }
98	  }
99	
100	  @IgnoreJRERequirement
101	  private static final class ResponseCallAdapter<R>
102	      implements CallAdapter<R, CompletableFuture<Response<R>>> {
103	    private final Type responseType;
104	
105	    ResponseCallAdapter(Type responseType) {
106	      this.responseType = responseType;
107	    }
108	
109	    @Override
110	    public Type responseType() {
111	      return responseType;
112	    }
113	
114	    @Override
115	    public CompletableFuture<Response<R>> adapt(final Call<R> call) {
116	      CompletableFuture<Response<R>> future = new CallCancelCompletableFuture<>(call);
117	      call.enqueue(new ResponseCallback(future));
118	      return future;
119	    }
120	
121	    @IgnoreJRERequirement
122	    private class ResponseCallback implements Callback<R> {
