24	/**
25	 * From Java 8 to Java 13, the only way to invoke a default method on a proxied interface is by
26	 * reflectively creating a trusted {@link Lookup} to invoke a method handle.
27	 * <p>
28	 * Note: This class has multi-release jar variants for newer versions of Java.
29	 */
30	final class DefaultMethodSupport {
31	  private static @Nullable Constructor<Lookup> lookupConstructor;
32	
33	  @IgnoreJRERequirement // Only used on JVM or Android API 24+.
34	  @Nullable
35	  static Object invoke(
36	      Method method, Class<?> declaringClass, Object proxy, @Nullable Object[] args)
37	      throws Throwable {
38	    Constructor<Lookup> constructor = lookupConstructor;
39	    if (constructor == null) {
40	      constructor = Lookup.class.getDeclaredConstructor(Class.class, int.class);
41	      constructor.setAccessible(true);
42	      lookupConstructor = constructor;
43	    }
44	    return constructor
45	        .newInstance(declaringClass, -1 /* trusted */)
46	        .unreflectSpecial(method, declaringClass)
47	        .bindTo(proxy)
48	        .invokeWithArguments(args);
49	  }
